Cache<Integer, Integer> cache = Caffeine.newBuilder()
    .maximumSize(100)
    .recordStats()
    .build();

cache.put(7, 49);
Integer value = cache.getIfPresent(7); // 49
cache.invalidate(7);
System.out.println(cache.getIfPresent(7)); // null

Cache<String, String> writeExpiring = Caffeine.newBuilder()
    .expireAfterWrite(Duration.ofMillis(300))
    .build();
writeExpiring.put("klucz", "wartosc");
// po 300ms OD ZAPISU wpis wygasa, niezaleznie od liczby odczytow

// cache-aside pattern:
Integer v = cache.getIfPresent(key);
if (v == null) {
    v = expensiveComputation(key);
    cache.put(key, v);
}

CacheStats stats = cache.stats();
System.out.printf("hitRate: %.2f%%%n", stats.hitRate() * 100);
